  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ 'ਜ਼ਿੰਦਗੀ' ਨੂੰ ਕਿਹੋ ਜਿਹਾ ਦੱਸਿਆ ਗਿਆ ਹੈ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵੀ ਪੰਜਾਬ ਦੀ ਸੁਰੱਖਿਆ ਲਈ ਕੀ ਪ੍ਰਾਰਥਨਾ ਕਰਦਾ ਹੈ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
