  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਬੇਹਿਸਾਬ' ਸ਼ਬਦ ਦਾ ਇੱਕ ਹੋਰ ਸਮਾਨਾਰਥੀ ਸ਼ਬਦ ਦੱਸੋ।$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਪੰਜਾਬ ਦੇ ਲੋਕਾਂ ਦੀ ਕਿਹੜੀ ਖਾਸੀਅਤ ਉੱਭਰ ਕੇ ਆਉਂਦੀ ਹੈ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਵਰਤੇ ਗਏ ਕਿਸੇ ਇੱਕ ਮੁਹਾਵਰੇ ਦੀ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ 'ਮੇਰਾ ਵੱਸਦਾ ਰਹੇ ਪੰਜਾਬ' ਦਾ ਕੇਂਦਰੀ ਭਾਵ ਵਿਸਥਾਰ ਸਹਿਤ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵੀ ਨੇ ਪੰਜਾਬ ਦੀ ਕੁਦਰਤੀ ਸੁੰਦਰਤਾ ਅਤੇ ਸੱਭਿਆਚਾਰਕ ਵਿਰਾਸਤ ਦਾ ਵਰਣਨ ਕਿਵੇਂ ਕੀਤਾ ਹੈ? ਵਿਸਥਾਰ ਵਿੱਚ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਪੰਜਾਬੀ ਲੋਕਾਂ ਦੇ ਜੀਵਨ ਢੰਗ, ਖੁਸ਼ੀਆਂ-ਗ਼ਮੀਆਂ ਵੰਡਣ ਦੇ ਤਰੀਕੇ ਅਤੇ ਮਿਲਣਸਾਰ ਸੁਭਾਅ ਬਾਰੇ ਕੀ ਦੱਸਿਆ ਗਿਆ ਹੈ? ਉਦਾਹਰਨਾਂ ਸਹਿਤ ਸਪੱਸ਼ਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਪੰਜ ਦਰਿਆਵਾਂ ਦੀ ਧਰਤੀ', 'ਗੁਰੂਆਂ-ਪੀਰਾਂ ਦੀ ਧਰਤੀ' ਅਤੇ 'ਸੋਨੇ ਰੰਗੀ ਮਿੱਟੀ' ਵਰਗੇ ਵਾਕੰਸ਼ਾਂ ਰਾਹੀਂ ਕਵੀ ਪੰਜਾਬ ਦੀ ਕਿਹੜੀ ਮਹੱਤਤਾ ਨੂੰ ਉਜਾਗਰ ਕਰਦਾ ਹੈ? ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
