  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਪੰਜਾਬੀ ਲੋਕਾਂ ਦੇ ਜੀਵਨ ਦੀਆਂ ਖੁਸ਼ੀਆਂ ਅਤੇ ਚੁਣੌਤੀਆਂ ਬਾਰੇ ਕੀ ਸੰਕੇਤ ਮਿਲਦੇ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਵਰਤੀ ਗਈ ਬਿੰਬਾਵਲੀ (imagery) ਦੀਆਂ ਉਦਾਹਰਨਾਂ ਦਿਓ ਅਤੇ ਉਹਨਾਂ ਦਾ ਪ੍ਰਭਾਵ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਦੇ ਸੰਦੇਸ਼ ਨੂੰ ਅਜੋਕੇ ਸਮੇਂ ਵਿੱਚ ਪੰਜਾਬ ਲਈ ਕਿਵੇਂ ਪ੍ਰਸੰਗਿਕ ਮੰਨਿਆ ਜਾ ਸਕਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ 'ਮੇਰਾ ਵੱਸਦਾ ਰਹੇ ਪੰਜਾਬ' ਦਾ ਕੇਂਦਰੀ ਭਾਵ ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਹਿਲੀ ਕਾਵਿ-ਟੁਕੜੀ ਦੀ ਪ੍ਰਸੰਗ ਸਹਿਤ ਵਿਆਖਿਆ ਕਰੋ ਅਤੇ ਇਸ ਵਿੱਚ ਪੰਜਾਬ ਦੀ ਕਿਹੜੀ ਤਸਵੀਰ ਪੇਸ਼ ਕੀਤੀ ਗਈ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਪੰਜਾਬ ਦੇ ਵੱਖ-ਵੱਖ ਵਰਗਾਂ ਦੇ ਲੋਕਾਂ ਦੀ ਕਿਹੜੀ ਭੂਮਿਕਾ ਦੱਸੀ ਗਈ ਹੈ? ਵਿਸਥਾਰ ਸਹਿਤ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵੀ ਪੰਜਾਬ ਪ੍ਰਤੀ ਆਪਣੀਆਂ ਭਾਵਨਾਵਾਂ ਅਤੇ ਇੱਛਾਵਾਂ ਨੂੰ ਕਿਵੇਂ ਪ੍ਰਗਟ ਕਰਦਾ ਹੈ? ਤੀਜੀ ਕਾਵਿ-ਟੁਕੜੀ ਦੇ ਸੰਦਰਭ ਵਿੱਚ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਮੇਰਾ ਵੱਸਦਾ ਰਹੇ ਪੰਜਾਬ' ਕਵਿਤਾ ਵਿੱਚ ਵਰਤੇ ਗਏ ਮੁੱਖ ਅਲੰਕਾਰਾਂ ਅਤੇ ਕਾਵਿ-ਜੁਗਤਾਂ ਦੀ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ 'ਝੰਡੇ ਗੱਡਣੇ', 'ਕੈਰੀ ਅੱਖ ਨਾਲ ਤੱਕਣਾ' ਅਤੇ 'ਚੰਦਰੇ ਦੀ ਨਜ਼ਰ ਨਾ ਲੱਗੇ' ਵਰਗੇ ਮੁਹਾਵਰਿਆਂ ਦੀ ਵਰਤੋਂ ਕਵਿਤਾ ਦੇ ਭਾਵ ਨੂੰ ਕਿਵੇਂ ਪ੍ਰਬਲ ਕਰਦੀ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵਿਤਾ ਵਿੱਚ ਪੰਜਾਬ ਦੇ ਕਿਸਾਨਾਂ, ਜਵਾਨਾਂ ਅਤੇ ਬੱਚਿਆਂ ਦੀ ਭੂਮਿਕਾ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਵੀ ਪੰਜਾਬ ਦੀ ਖੁਸ਼ਹਾਲੀ ਅਤੇ ਸੁਰੱਖਿਆ ਲਈ ਕੀ ਪ੍ਰਾਰਥਨਾ ਕਰਦਾ ਹੈ? ਇਸ ਪ੍ਰਾਰਥਨਾ ਦਾ ਕੀ ਮਹੱਤਵ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
