  ('8160e499-70bb-41c6-826d-718246fff427', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '7da9339c-b34f-4aac-9eec-bd95b9b553b6', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੈਂ ਪੰਜਾਬੀ, ਮੇਰੀ ਮਾਂ ਪੰਜਾਬੀ, ਮੈਂ ਬੋਲਾਂ ਪੰਜਾਬੀ, ਮੇਰਾ ਵੱਸਦਾ ਰਹੇ ਪੰਜਾਬ, ਖਿੜਿਆ ਰਹੇ ਇਹੋ ਵਾਂਗ ਗੁਲਾਬ। ਪੰਜ ਦਰਿਆਵਾਂ ਦੀ ਧਰਤੀ ਦਾ, ਇਹ ਹੈ ਸੁੰਦਰ ਗਹਿਣਾ, ਇਸ ਦੀ ਹਰ ਇੱਕ ਸ਼ੈ ਅਨੋਖੀ, ਇਸ ਦਾ ਕੀ ਹੈ ਕਹਿਣਾ। ਮਾਣ ਹੈ ਮੈਨੂੰ ਇਸ ਦੇ ਉੱਤੇ, ਇਹ ਹੈ ਆਫ਼ਤਾਬ, ਮੇਰਾ ਵੱਸਦਾ ਰਹੇ ਪੰਜਾਬ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-966Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
